		t.Fatal(err)
	}
	if _, err := r.Adjust("A0", []Op{
		{Kind: OpLoad, CargoID: "G1", Target: "C1"},
		{Kind: OpLoad, CargoID: "G2", Target: "C1"},
	}); err != nil {
		t.Fatal(err)
	}
	// 30 -> 90：预计合计 110 超过承重 100。
	se := requireError(t, r.AmendCargo("G1", 90, "X", true), ErrOverweight)
