		{Kind: OpLoad, CargoID: "G2", Target: "C1"},
	}); err != nil {
		t.Fatal(err)
	}
	// 已装载时提交完全相同的资料：成功、重量不重复计入、舱位不变。
	if err := r.AmendCargo("G1", 30, " Shanghai ", false); err != nil {
